public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int n = strings.size();
    // Precompute substring sets for each string
    List<HashSet<String>> substringSets = new ArrayList<>(n);
    for (String s : strings) {
        HashSet<String> set = new HashSet<>();
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                set.add(s.substring(i, j));
            }
        }
        substringSets.add(set);
    }
    String first = strings.get(0);
    int firstLen = first.length();
    // Try lengths from longest to shortest
    for (int L = firstLen; L >= 1; L--) {
        for (int i = 0; i + L <= firstLen; i++) {
            String sub = first.substring(i, i + L);
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (int k = 1; k < n; k++) { // skip first string
                HashSet<String> set = substringSets.get(k);
                if (!set.contains(sub) && !set.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return L;
            }
        }
    }
    return 0;
}

