public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] timeNeeded = new int[n];
    java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
    stack.push(new int[]{0, -1, 0});
    while (!stack.isEmpty()) {
        int[] cur = stack.pop();
        int node = cur[0];
        int parent = cur[1];
        int state = cur[2];
        if (state == 0) {
            stack.push(new int[]{node, parent, 1});
            for (int neighbor : graph[node]) {
                if (neighbor != parent) {
                    stack.push(new int[]{neighbor, node, 0});
                }
            }
        } else {
            int time = 0;
            for (int neighbor : graph[node]) {
                if (neighbor != parent) {
                    if (timeNeeded[neighbor] > 0 || hasApple[neighbor]) {
                        time += timeNeeded[neighbor] + 2;
                    }
                }
            }
            timeNeeded[node] = time;
        }
    }
    return timeNeeded[0];
}

