public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    int maxVal = A[n - 1];
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    int fullMask = (1 << n) - 1;
    int[][] memo = new int[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(memo[i], -1);
    }
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int last) {
            if (mask == fullMask) return 1;
            int memoVal = memo[mask][last];
            if (memoVal != -1) return memoVal;
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (isSquare[A[last] + A[i]]) {
                    if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                    count += dfs.applyAsInt(mask | (1 << i), i);
                }
            }
            memo[mask][last] = count;
            return count;
        }
    };
    int result = 0;
    for (int i = 0; i < n; i++) {
        if (i > 0 && A[i] == A[i - 1] && (1 << (i - 1)) == 0) continue; // skip duplicate starts
        result += dfs.applyAsInt(1 << i, i);
    }
    return result;
}

